const OPERATIONS = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => a / b
};

export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number' },
          b: { type: 'number' },
          operation: { type: 'string', enum: ['add', 'subtract', 'multiply', 'divide'] }
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const allowed = ['a', 'b', 'operation'];
  const provided = Object.keys(args || {});
  for (const key of provided) {
    if (!allowed.includes(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (!('a' in args)) throw new Error('Missing required field: a');
  if (!('b' in args)) throw new Error('Missing required field: b');
  if (!('operation' in args)) throw new Error('Missing required field: operation');

  const { a, b, operation } = args;

  if (typeof a !== 'number' || Number.isNaN(a)) throw new Error('a must be a number');
  if (typeof b !== 'number' || Number.isNaN(b)) throw new Error('b must be a number');
  if (!(operation in OPERATIONS)) throw new Error(`Unsupported operation: ${operation}`);

  if (operation === 'divide' && b === 0) {
    throw new Error('Division by zero');
  }

  const result = OPERATIONS[operation](a, b);
  return { content: [{ type: 'text', text: String(result) }] };
}
```

